RULES = ['prefer verb over noun']
def rewrite(phi, llm):
    return llm(f'rules={RULES}; rewrite once: {phi}')

import torch, torch.nn as nn
class SceneEncoder(nn.Module):
    def __init__(self, d=256, M=16):
        super().__init__()
        self.q = nn.Parameter(torch.randn(M, d))
    def forward(self, views, poses):
        pooled = views.mean(1, keepdim=True)  # [B,1,d]
        return self.q.unsqueeze(0) + pooled      # [B,M,d]，与 K 无关

import torch.nn.functional as F
def tv_pred_loss(decoder, z, P_t, I_t):
    I_hat = decoder(z, P_t)
    return F.l1_loss(I_hat, I_t)

import statistics
def selection_gain(perf_top, perf_rand_list):
    return perf_top - statistics.mean(perf_rand_list)

import itertools
def ranking_acc(p_hat, p):
    ok=tot=0
    for a,b in itertools.combinations(range(len(p)),2):
        ok += ((p_hat[a]-p_hat[b])*(p[a]-p[b])>0); tot+=1
    return ok/tot
